<script setup>
import { ref, onMounted, reactive } from 'vue'
import AppLayout from '@/Components/Layout/AppLayout.vue'
import Button from '@/Components/Common/Button.vue'
import Input from '@/Components/Forms/Input.vue'
import $ from 'jquery'
import 'datatables.net'
import axios from 'axios'
const props = defineProps({
  branches: Array
})

const tableSearch = ref(''), perPage = ref(10)
const mobileItems = ref([]), mobileLoading = ref(true), mobileCurrentPage = ref(1), mobileTotalPages = ref(1), mobileTotal = ref(0), mobileOffset = ref(0)
let table = null
const filters = reactive({ search: '', branch_id: '', month: '' })
const loadMobileData = async () => { mobileLoading.value = true; try { const params = { page: mobileCurrentPage.value, per_page: perPage.value, mobile: 1 }; if (filters.search) params.search = filters.search; if (filters.branch_id) params.branch_id = filters.branch_id; if (filters.month) params.month = filters.month; if (tableSearch.value) params.search = tableSearch.value; const response = await axios.get(route('fee-collection-summaries.index'), { params, headers: { 'X-Requested-With': 'XMLHttpRequest', 'Accept': 'application/json' } }); if (response.data?.data) { mobileItems.value = response.data.data; mobileCurrentPage.value = response.data.current_page || 1; mobileTotalPages.value = response.data.last_page || 1; mobileTotal.value = response.data.total || 0; mobileOffset.value = response.data.from ? response.data.from - 1 : 0 } else if (Array.isArray(response.data)) { mobileItems.value = response.data; mobileTotalPages.value = 1; mobileTotal.value = response.data.length; mobileOffset.value = 0 } } catch (e) { mobileItems.value = []; mobileTotal.value = 0 } finally { mobileLoading.value = false } }
