st: '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 19l-7-7 7-7m8 14l-7-7 7-7"/></svg>', last: '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 5l7 7-7 7M5 5l7 7-7 7"/></svg>', next: '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>', previous: '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/></svg>' } }, drawCallback: function () { $('#table-info').empty().append($('#fee-collection-summaries-table_info')); $('#table-pagination').empty().append($('#fee-collection-summaries-table_paginate')) } }) })
const prevPage = () => { if (mobileCurrentPage.value > 1 && !mobileLoading.value) { mobileCurrentPage.value--; loadMobileData(); window.scrollTo({ top: 0, behavior: 'smooth' }) } }
const nextPage = () => { if (mobileCurrentPage.value < mobileTotalPages.value && !mobileLoading.value) { mobileCurrentPage.value++; loadMobileData(); window.scrollTo({ top: 0, behavior: 'smooth' }) } }
let tableSearchTimeout = null; const tableSearchDebounced = () => { clearTimeout(tableSearchTimeout); tableSearchTimeout = setTimeout(() => loadData(), 500) }
let searchTimeout = null; const searchDebounced = () => { clearTimeout(searchTimeout); searchTimeout = setTimeout(() => loadData(), 500) }
const changePerPage = () => { if (table) table.page.len(perPage.value).draw(); mobileCurrentPage.value = 1; loadMobileData() }
const loadData = () => { if (table) table.ajax.reload(); mobileCurrentPage.value = 1; loadMobileData() }
const resetFilters = () => { filters.search = ''; filters.branch_id = ''; filters.month = ''; tableSearch.value = ''; loadData() }
</script>
